  ('ai:ai-batch-08:ccaddc716e70','B1'::public.cefr_level,'grammar','The concert, ___ lasted three hours, was fantastic.',array['who','that','which','what']::text[],'C','Non-defining relative clause: which.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
