  ('ai:ai-batch-08:e0ff234d1d8b','B1'::public.cefr_level,'grammar','She ___ have forgotten — I reminded her twice.',array['can''t','shouldn''t','needn''t','mustn''t']::text[],'A','''Can''t have'' = it''s impossible that she forgot.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
