  ('ai:ai-batch-08:b5d419e7c379','B1'::public.cefr_level,'grammar','The students were made ___ the room.',array['tidied','tidying','to tidy','tidy']::text[],'C','In the passive, ''make'' takes ''to''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
