  ('ai:ai-batch-08:66c3594258de','B1'::public.cefr_level,'vocabulary','All the tickets were sold ___ in an hour.',array['away','up','off','out']::text[],'D','''Sold out'' = none left.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
