  ('ai:ai-batch-08:d34c8c47c20a','B2'::public.cefr_level,'grammar','I regret ___ harder at school.',array['to not study','not to study','don''t study','not studying']::text[],'D','''Regret'' + -ing for past actions.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
