  ('ai:ai-batch-08:68f2385ac56a','B2'::public.cefr_level,'vocabulary','The ___ for the competition is midnight on Friday.',array['timeline','dead end','deadline','finishing line']::text[],'C','A deadline = latest time to do something.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:696f27f3af43','B2'::public.cefr_level,'vocabulary','I''m afraid I can''t ___ your invitation.',array['expect','except','exempt','accept']::text[],'D','Accept = agree to receive.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:6fd7e5013b23','B2'::public.cefr_level,'reading','What is ''fast fashion'', according to the text?',array['second-hand clothing','cheap clothing made quickly to follow trends','clothes made to last for years','expensive designer clothes']::text[],'B','''...cheap clothing produced quickly to follow the latest trends.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fast fashion — cheap clothing produced quickly to follow the latest trends — has transformed the way we shop. Clothes that once lasted for years are now worn a handful of times before being thrown away. The environmental cost is considerable: the textile industry uses vast amounts of water and produces a significant share of global carbon emissions. In response, some brands now offer repair services or buy back old items to resell. Critics argue, however, that such schemes are small compared with the overall volume of clothing produced, and that real change requires consumers to buy less.',null,null,null,'practice'),
  ('ai:ai-batch-08:128f42b0eb67','B2'::public.cefr_level,'reading','Which environmental problem of the textile industry is mentioned?',array['plastic packaging','high water use','loss of farmland','noise pollution']::text[],'B','''...the textile industry uses vast amounts of water.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fast fashion — cheap clothing produced quickly to follow the latest trends — has transformed the way we shop. Clothes that once lasted for years are now worn a handful of times before being thrown away. The environmental cost is considerable: the textile industry uses vast amounts of water and produces a significant share of global carbon emissions. In response, some brands now offer repair services or buy back old items to resell. Critics argue, however, that such schemes are small compared with the overall volume of clothing produced, and that real change requires consumers to buy less.',null,null,null,'practice'),
  ('ai:ai-batch-08:bb34207d5911','B2'::public.cefr_level,'reading','What have some brands started doing?',array['stopping all production','using only cotton','offering repairs or buying back old clothes','raising prices sharply']::text[],'C','''...some brands now offer repair services or buy back old items to resell.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fast fashion — cheap clothing produced quickly to follow the latest trends — has transformed the way we shop. Clothes that once lasted for years are now worn a handful of times before being thrown away. The environmental cost is considerable: the textile industry uses vast amounts of water and produces a significant share of global carbon emissions. In response, some brands now offer repair services or buy back old items to resell. Critics argue, however, that such schemes are small compared with the overall volume of clothing produced, and that real change requires consumers to buy less.',null,null,null,'practice'),
  ('ai:ai-batch-08:6775ed68fcd9','B2'::public.cefr_level,'reading','What do critics believe real change requires?',array['new technology','cheaper clothes','consumers buying less','more repair services']::text[],'C','''...real change requires consumers to buy less.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fast fashion — cheap clothing produced quickly to follow the latest trends — has transformed the way we shop. Clothes that once lasted for years are now worn a handful of times before being thrown away. The environmental cost is considerable: the textile industry uses vast amounts of water and produces a significant share of global carbon emissions. In response, some brands now offer repair services or buy back old items to resell. Critics argue, however, that such schemes are small compared with the overall volume of clothing produced, and that real change requires consumers to buy less.',null,null,null,'practice'),
  ('ai:ai-batch-08:38db074ecb23','B2'::public.cefr_level,'reading','Why do most employees value hybrid working?',array['Offices are uncomfortable.','They earn more.','It saves time on commuting.','They work fewer hours.']::text[],'C','''...citing the time saved on commuting.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Since the pandemic, many employers have adopted hybrid working, with staff splitting their week between home and the office. Surveys suggest that most employees value the flexibility, citing the time saved on commuting. Managers, however, have raised concerns about the loss of informal learning that happens when junior staff can overhear and observe experienced colleagues. Some companies now require new employees to spend more days in the office during their first year, precisely to address this issue.',null,null,null,'practice'),
  ('ai:ai-batch-08:f763dc54d379','B2'::public.cefr_level,'reading','What concern have managers raised?',array['Staff work too late.','Productivity has fallen.','Offices are too empty.','Junior staff miss informal learning.']::text[],'D','''...the loss of informal learning that happens when junior staff can overhear and observe experienced colleagues.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Since the pandemic, many employers have adopted hybrid working, with staff splitting their week between home and the office. Surveys suggest that most employees value the flexibility, citing the time saved on commuting. Managers, however, have raised concerns about the loss of informal learning that happens when junior staff can overhear and observe experienced colleagues. Some companies now require new employees to spend more days in the office during their first year, precisely to address this issue.',null,null,null,'practice'),
  ('ai:ai-batch-08:7fafcd0ec597','B2'::public.cefr_level,'reading','What do some companies now require of new employees?',array['working from home full-time','a longer contract','extra training courses online','more days in the office in their first year']::text[],'D','''...require new employees to spend more days in the office during their first year.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Since the pandemic, many employers have adopted hybrid working, with staff splitting their week between home and the office. Surveys suggest that most employees value the flexibility, citing the time saved on commuting. Managers, however, have raised concerns about the loss of informal learning that happens when junior staff can overhear and observe experienced colleagues. Some companies now require new employees to spend more days in the office during their first year, precisely to address this issue.',null,null,null,'practice'),
  ('ai:ai-batch-08:462a41b41ed7','B2'::public.cefr_level,'reading','What proportion of crops do bees help to pollinate?',array['almost all','half','around a third','about a tenth']::text[],'C','''...pollinating around a third of the crops we eat.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Bees play a vital role in food production, pollinating around a third of the crops we eat. In recent decades, however, many bee populations have declined sharply. Scientists point to several causes, including the loss of wildflower habitats, the use of certain pesticides and the spread of diseases. Gardeners can help by planting a variety of flowers that bloom at different times of the year, so that bees have a source of food from spring to autumn.',null,null,null,'practice'),
  ('ai:ai-batch-08:75fbcc5fc5eb','B2'::public.cefr_level,'reading','Which cause of bee decline is NOT mentioned?',array['loss of wildflower habitats','diseases','certain pesticides','climate change']::text[],'D','The causes listed are habitat loss, pesticides and diseases.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Bees play a vital role in food production, pollinating around a third of the crops we eat. In recent decades, however, many bee populations have declined sharply. Scientists point to several causes, including the loss of wildflower habitats, the use of certain pesticides and the spread of diseases. Gardeners can help by planting a variety of flowers that bloom at different times of the year, so that bees have a source of food from spring to autumn.',null,null,null,'practice'),
  ('ai:ai-batch-08:cef661dadbdf','B2'::public.cefr_level,'reading','Why should gardeners plant flowers that bloom at different times?',array['to attract more birds','to avoid pesticides','so bees have food from spring to autumn','to make gardens look better']::text[],'C','''...so that bees have a source of food from spring to autumn.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Bees play a vital role in food production, pollinating around a third of the crops we eat. In recent decades, however, many bee populations have declined sharply. Scientists point to several causes, including the loss of wildflower habitats, the use of certain pesticides and the spread of diseases. Gardeners can help by planting a variety of flowers that bloom at different times of the year, so that bees have a source of food from spring to autumn.',null,null,null,'practice'),
  ('ai:ai-batch-08:8dd3b6e8e413','B2'::public.cefr_level,'reading','Since when have most national museums been free?',array['2010','2001','1990','they have always been free']::text[],'B','''...have been free to enter since 2001.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Most of the UK''s national museums, such as the British Museum and the Natural History Museum, have been free to enter since 2001. Supporters of free entry argue that it makes culture accessible to everyone, regardless of income, and point out that visitor numbers rose substantially after charges were removed. Opponents counter that museums are struggling with rising costs and that overseas tourists, who make up a large proportion of visitors, could reasonably be asked to pay.',null,null,null,'practice'),
  ('ai:ai-batch-08:5807d3a4b195','B2'::public.cefr_level,'reading','What happened when charges were removed?',array['Visitor numbers rose substantially.','Fewer tourists came.','Prices for exhibitions fell.','Museums closed.']::text[],'A','''...visitor numbers rose substantially after charges were removed.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Most of the UK''s national museums, such as the British Museum and the Natural History Museum, have been free to enter since 2001. Supporters of free entry argue that it makes culture accessible to everyone, regardless of income, and point out that visitor numbers rose substantially after charges were removed. Opponents counter that museums are struggling with rising costs and that overseas tourists, who make up a large proportion of visitors, could reasonably be asked to pay.',null,null,null,'practice'),
  ('ai:ai-batch-08:08db45a5a2c6','B2'::public.cefr_level,'reading','What do opponents of free entry suggest?',array['charging only children','closing some museums','raising taxes','charging overseas tourists']::text[],'D','''...overseas tourists... could reasonably be asked to pay.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Most of the UK''s national museums, such as the British Museum and the Natural History Museum, have been free to enter since 2001. Supporters of free entry argue that it makes culture accessible to everyone, regardless of income, and point out that visitor numbers rose substantially after charges were removed. Opponents counter that museums are struggling with rising costs and that overseas tourists, who make up a large proportion of visitors, could reasonably be asked to pay.',null,null,null,'practice'),
  ('ai:ai-batch-08:559b03c36026','B2'::public.cefr_level,'reading','What is the main argument for free entry?',array['It saves museums money.','Culture should be accessible to everyone.','It reduces crowds.','It attracts more tourists from abroad.']::text[],'B','''...it makes culture accessible to everyone, regardless of income.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Most of the UK''s national museums, such as the British Museum and the Natural History Museum, have been free to enter since 2001. Supporters of free entry argue that it makes culture accessible to everyone, regardless of income, and point out that visitor numbers rose substantially after charges were removed. Opponents counter that museums are struggling with rising costs and that overseas tourists, who make up a large proportion of visitors, could reasonably be asked to pay.',null,null,null,'practice'),
  ('ai:ai-batch-08:e26e5399c181','B2'::public.cefr_level,'reading','What happened in 1997?',array['A computer beat the world chess champion.','Chess was invented.','Kasparov became champion.','Online chess began.']::text[],'A','''...Deep Blue defeated the world champion Garry Kasparov.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','For centuries chess was seen as the ultimate test of human intelligence. That view changed in 1997, when IBM''s computer Deep Blue defeated the world champion Garry Kasparov. Today, chess programs running on an ordinary phone can beat any human player. Paradoxically, though, chess has never been more popular. Online platforms allow millions of people to play against each other, and players use computers not as rivals but as training partners, analysing their games to discover mistakes.',null,null,null,'practice'),
  ('ai:ai-batch-08:fbfba7be62ef','B2'::public.cefr_level,'reading','What is ''paradoxical'' about chess today?',array['Computers are better than humans, yet chess is more popular than ever.','It is played less but watched more.','It has become easier.','Only computers play it.']::text[],'A','''Paradoxically, though, chess has never been more popular.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','For centuries chess was seen as the ultimate test of human intelligence. That view changed in 1997, when IBM''s computer Deep Blue defeated the world champion Garry Kasparov. Today, chess programs running on an ordinary phone can beat any human player. Paradoxically, though, chess has never been more popular. Online platforms allow millions of people to play against each other, and players use computers not as rivals but as training partners, analysing their games to discover mistakes.',null,null,null,'practice'),
  ('ai:ai-batch-08:0d4222f1bad1','B2'::public.cefr_level,'reading','How do players use computers today?',array['to replace teachers completely','to cheat in tournaments','as training partners to analyse games','only as opponents']::text[],'C','''...players use computers not as rivals but as training partners.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','For centuries chess was seen as the ultimate test of human intelligence. That view changed in 1997, when IBM''s computer Deep Blue defeated the world champion Garry Kasparov. Today, chess programs running on an ordinary phone can beat any human player. Paradoxically, though, chess has never been more popular. Online platforms allow millions of people to play against each other, and players use computers not as rivals but as training partners, analysing their games to discover mistakes.',null,null,null,'practice'),
  ('ai:ai-batch-08:686c9b873fda','B2'::public.cefr_level,'reading','What is the purpose of J. Patel''s letter?',array['to complain about noise','to ask for new books','to oppose the library''s closure','to praise the council']::text[],'C','''I was disappointed to read that the council intends to close the library.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Dear Editor, I was disappointed to read that the council intends to close the library on Park Street. For many residents, particularly older people and families without internet access at home, the library is far more than a place to borrow books. It offers free computer use, help with job applications and a warm, safe place to spend time. While I understand the need to save money, I would urge the council to consider alternatives, such as sharing the building with other community services. Yours faithfully, J. Patel',null,null,null,'practice'),
  ('ai:ai-batch-08:fab120f7704d','B2'::public.cefr_level,'reading','According to the writer, who depends most on the library?',array['older people and families without internet','council staff','tourists','students only']::text[],'A','''...particularly older people and families without internet access at home.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Dear Editor, I was disappointed to read that the council intends to close the library on Park Street. For many residents, particularly older people and families without internet access at home, the library is far more than a place to borrow books. It offers free computer use, help with job applications and a warm, safe place to spend time. While I understand the need to save money, I would urge the council to consider alternatives, such as sharing the building with other community services. Yours faithfully, J. Patel',null,null,null,'practice'),
  ('ai:ai-batch-08:c87c3730549d','B2'::public.cefr_level,'reading','What alternative does the writer suggest?',array['sharing the building with other services','selling the building','charging for books','opening only at weekends']::text[],'A','''...such as sharing the building with other community services.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Dear Editor, I was disappointed to read that the council intends to close the library on Park Street. For many residents, particularly older people and families without internet access at home, the library is far more than a place to borrow books. It offers free computer use, help with job applications and a warm, safe place to spend time. While I understand the need to save money, I would urge the council to consider alternatives, such as sharing the building with other community services. Yours faithfully, J. Patel',null,null,null,'practice'),
  ('ai:ai-batch-08:8d6e36560cb4','B2'::public.cefr_level,'reading','What does the writer accept?',array['that the building is unsafe','that the library is unused','that the council needs to save money','that books are old-fashioned']::text[],'C','''While I understand the need to save money...''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Dear Editor, I was disappointed to read that the council intends to close the library on Park Street. For many residents, particularly older people and families without internet access at home, the library is far more than a place to borrow books. It offers free computer use, help with job applications and a warm, safe place to spend time. While I understand the need to save money, I would urge the council to consider alternatives, such as sharing the building with other community services. Yours faithfully, J. Patel',null,null,null,'practice'),
  ('ai:ai-batch-08:c95be005aece','B2'::public.cefr_level,'reading','Why is it natural for teenagers to sleep later?',array['They use phones at night.','They are less active.','Their internal clock shifts during adolescence.','They have more homework.']::text[],'C','''During adolescence, the body''s internal clock shifts.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Research into teenagers'' sleep has led some experts to argue that school should start later. During adolescence, the body''s internal clock shifts, making it natural for teenagers to fall asleep and wake up later than adults. A study of schools that delayed their start time by an hour found improvements in attendance and exam results. However, critics note practical difficulties: later finishes could clash with after-school jobs and sports, and parents who work standard hours might struggle with transport.',null,null,null,'practice'),
  ('ai:ai-batch-08:7bf66ca8e630','B2'::public.cefr_level,'reading','What did the study find in schools that started later?',array['better attendance and exam results','fewer teachers','more sports participation','longer school days']::text[],'A','''...found improvements in attendance and exam results.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Research into teenagers'' sleep has led some experts to argue that school should start later. During adolescence, the body''s internal clock shifts, making it natural for teenagers to fall asleep and wake up later than adults. A study of schools that delayed their start time by an hour found improvements in attendance and exam results. However, critics note practical difficulties: later finishes could clash with after-school jobs and sports, and parents who work standard hours might struggle with transport.',null,null,null,'practice'),
  ('ai:ai-batch-08:a29284ae08f4','B2'::public.cefr_level,'reading','What practical difficulty do critics mention?',array['clashes with after-school jobs and sports','fewer teachers available','students sleeping in class','higher costs for schools']::text[],'A','''...later finishes could clash with after-school jobs and sports.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Research into teenagers'' sleep has led some experts to argue that school should start later. During adolescence, the body''s internal clock shifts, making it natural for teenagers to fall asleep and wake up later than adults. A study of schools that delayed their start time by an hour found improvements in attendance and exam results. However, critics note practical difficulties: later finishes could clash with after-school jobs and sports, and parents who work standard hours might struggle with transport.',null,null,null,'practice'),
  ('ai:ai-batch-08:d1f45a3566af','B2'::public.cefr_level,'reading','What does a ''best before'' date refer to?',array['price','safety','the date it was produced','quality']::text[],'D','''A ''best before'' date refers to quality.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In the UK, households throw away millions of tonnes of food every year, much of it still edible. Common reasons include buying too much, misunderstanding date labels and poor storage. A ''best before'' date refers to quality, meaning food is often safe to eat afterwards, whereas a ''use by'' date relates to safety and should be followed. Some supermarkets have begun removing ''best before'' dates from fresh fruit and vegetables to encourage customers to judge food for themselves.',null,null,null,'practice'),
  ('ai:ai-batch-08:57b1f0a9ee4a','B2'::public.cefr_level,'reading','Which date should always be followed for safety?',array['display until','use by','best before','sell by']::text[],'B','''...a ''use by'' date relates to safety and should be followed.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In the UK, households throw away millions of tonnes of food every year, much of it still edible. Common reasons include buying too much, misunderstanding date labels and poor storage. A ''best before'' date refers to quality, meaning food is often safe to eat afterwards, whereas a ''use by'' date relates to safety and should be followed. Some supermarkets have begun removing ''best before'' dates from fresh fruit and vegetables to encourage customers to judge food for themselves.',null,null,null,'practice'),
  ('ai:ai-batch-08:5c63e0984cfc','B2'::public.cefr_level,'reading','Why have some supermarkets removed ''best before'' dates from fresh produce?',array['to save printing costs','to encourage customers to judge food themselves','to sell food faster','because of a new law']::text[],'B','''...to encourage customers to judge food for themselves.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In the UK, households throw away millions of tonnes of food every year, much of it still edible. Common reasons include buying too much, misunderstanding date labels and poor storage. A ''best before'' date refers to quality, meaning food is often safe to eat afterwards, whereas a ''use by'' date relates to safety and should be followed. Some supermarkets have begun removing ''best before'' dates from fresh fruit and vegetables to encourage customers to judge food for themselves.',null,null,null,'practice'),
  ('ai:ai-batch-08:79d5d9779610','B2'::public.cefr_level,'reading','Which reason for food waste is NOT mentioned?',array['food being too expensive','buying too much','misunderstanding labels','poor storage']::text[],'A','The reasons given are buying too much, labels and storage.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In the UK, households throw away millions of tonnes of food every year, much of it still edible. Common reasons include buying too much, misunderstanding date labels and poor storage. A ''best before'' date refers to quality, meaning food is often safe to eat afterwards, whereas a ''use by'' date relates to safety and should be followed. Some supermarkets have begun removing ''best before'' dates from fresh fruit and vegetables to encourage customers to judge food for themselves.',null,null,null,'practice'),
  ('ai:ai-batch-08:10d5e5ce36b3','B2'::public.cefr_level,'reading','How did Laura Bingham survive her journey?',array['Sponsors paid for hotels.','She relied on strangers'' kindness.','She worked in each country.','She carried all her food.']::text[],'B','''...relying entirely on the kindness of strangers for food and shelter.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','At 23, Laura Bingham cycled across South America without any money, relying entirely on the kindness of strangers for food and shelter. She described the journey as the hardest thing she had ever done, but also the most rewarding. ''I learned that people are overwhelmingly generous,'' she later said. Her trip raised money for a charity supporting street children, and she has since completed several other expeditions, including a descent of the Essequibo River in Guyana.',null,null,null,'practice'),
  ('ai:ai-batch-08:8dcc75426306','B2'::public.cefr_level,'reading','What did Laura learn from the trip?',array['that cycling is easy','that people are very generous','that travel is dangerous','that she prefers to travel alone']::text[],'B','''I learned that people are overwhelmingly generous.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','At 23, Laura Bingham cycled across South America without any money, relying entirely on the kindness of strangers for food and shelter. She described the journey as the hardest thing she had ever done, but also the most rewarding. ''I learned that people are overwhelmingly generous,'' she later said. Her trip raised money for a charity supporting street children, and she has since completed several other expeditions, including a descent of the Essequibo River in Guyana.',null,null,null,'practice'),
  ('ai:ai-batch-08:000a31881cbb','B2'::public.cefr_level,'reading','What was the purpose of the trip, apart from adventure?',array['to find a job','to write a guidebook','to study languages','to raise money for a charity']::text[],'D','''Her trip raised money for a charity supporting street children.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','At 23, Laura Bingham cycled across South America without any money, relying entirely on the kindness of strangers for food and shelter. She described the journey as the hardest thing she had ever done, but also the most rewarding. ''I learned that people are overwhelmingly generous,'' she later said. Her trip raised money for a charity supporting street children, and she has since completed several other expeditions, including a descent of the Essequibo River in Guyana.',null,null,null,'practice'),
  ('ai:ai-batch-08:07f415e1ca33','B2'::public.cefr_level,'reading','How did many institutions first respond to AI writing tools?',array['They ignored them.','They used them to mark essays.','They tried to ban them.','They welcomed them immediately.']::text[],'C','''Some institutions initially tried to ban them.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Artificial intelligence tools that can write essays have caused alarm in schools and universities. Some institutions initially tried to ban them, but many have since accepted that such tools are here to stay. Instead, teachers are redesigning assignments: more work is done in class, oral presentations are being reintroduced, and students may be asked to explain how they reached their conclusions. Some educators argue that learning to use these tools critically is itself an important skill.',null,null,null,'practice'),
  ('ai:ai-batch-08:d09096e7634d','B2'::public.cefr_level,'reading','How are teachers changing assignments?',array['only online tests','longer homework essays','more in-class work and oral presentations','removing all exams']::text[],'C','''...more work is done in class, oral presentations are being reintroduced.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Artificial intelligence tools that can write essays have caused alarm in schools and universities. Some institutions initially tried to ban them, but many have since accepted that such tools are here to stay. Instead, teachers are redesigning assignments: more work is done in class, oral presentations are being reintroduced, and students may be asked to explain how they reached their conclusions. Some educators argue that learning to use these tools critically is itself an important skill.',null,null,null,'practice'),
  ('ai:ai-batch-08:c741508fa030','B2'::public.cefr_level,'reading','What do some educators believe?',array['Using AI tools critically is an important skill.','AI tools should be banned forever.','Teachers will be replaced.','Students no longer need to write.']::text[],'A','''...learning to use these tools critically is itself an important skill.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Artificial intelligence tools that can write essays have caused alarm in schools and universities. Some institutions initially tried to ban them, but many have since accepted that such tools are here to stay. Instead, teachers are redesigning assignments: more work is done in class, oral presentations are being reintroduced, and students may be asked to explain how they reached their conclusions. Some educators argue that learning to use these tools critically is itself an important skill.',null,null,null,'practice'),
  ('ai:ai-batch-08:29de40b37bba','B2'::public.cefr_level,'reading','What do users say fitness trackers do?',array['cure sleep problems','replace doctors','motivate them to be more active','always measure perfectly']::text[],'C','''...seeing their data motivates them to be more active.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fitness trackers that count steps and monitor sleep have become increasingly popular. Users often report that seeing their data motivates them to be more active. Yet researchers warn that the devices are not always accurate, particularly when measuring sleep, and that some users become anxious about their numbers. Doctors suggest treating the data as a general guide rather than a precise measurement, and focusing on long-term trends rather than daily scores.',null,null,null,'practice'),
  ('ai:ai-batch-08:0a98b6dc0e30','B2'::public.cefr_level,'reading','Which measurement is especially unreliable, according to researchers?',array['steps','sleep','heart rate during exercise','distance walked']::text[],'B','''...not always accurate, particularly when measuring sleep.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fitness trackers that count steps and monitor sleep have become increasingly popular. Users often report that seeing their data motivates them to be more active. Yet researchers warn that the devices are not always accurate, particularly when measuring sleep, and that some users become anxious about their numbers. Doctors suggest treating the data as a general guide rather than a precise measurement, and focusing on long-term trends rather than daily scores.',null,null,null,'practice'),
  ('ai:ai-batch-08:5fd6d7c33b55','B2'::public.cefr_level,'reading','What do doctors advise?',array['Check the data every hour.','Stop using the devices.','Focus on long-term trends, not daily scores.','Trust the exact numbers.']::text[],'C','''...focusing on long-term trends rather than daily scores.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fitness trackers that count steps and monitor sleep have become increasingly popular. Users often report that seeing their data motivates them to be more active. Yet researchers warn that the devices are not always accurate, particularly when measuring sleep, and that some users become anxious about their numbers. Doctors suggest treating the data as a general guide rather than a precise measurement, and focusing on long-term trends rather than daily scores.',null,null,null,'practice'),
  ('ai:ai-batch-08:aae8be039394','B2'::public.cefr_level,'reading','What possible downside of trackers is mentioned?',array['They are very expensive.','They are hard to use.','Some users become anxious about their numbers.','They stop people sleeping.']::text[],'C','''...some users become anxious about their numbers.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Fitness trackers that count steps and monitor sleep have become increasingly popular. Users often report that seeing their data motivates them to be more active. Yet researchers warn that the devices are not always accurate, particularly when measuring sleep, and that some users become anxious about their numbers. Doctors suggest treating the data as a general guide rather than a precise measurement, and focusing on long-term trends rather than daily scores.',null,null,null,'practice'),
  ('ai:ai-batch-08:f69a548625fd','B2'::public.cefr_level,'reading','What benefit of volunteering is linked to older people?',array['better pay','new qualifications','more travel','lower stress and depression']::text[],'D','''...lower levels of stress and depression, especially among older people.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Volunteering is often presented as a selfless act, but research suggests it benefits volunteers too. Studies have linked regular volunteering with lower levels of stress and depression, especially among older people. Volunteering can also help younger people gain skills and experience that employers value. However, charities warn that volunteers need proper support and training; without it, they may feel undervalued and give up.',null,null,null,'practice'),
  ('ai:ai-batch-08:0a93f20dda0e','B2'::public.cefr_level,'reading','How can volunteering help younger people?',array['by paying for university','by giving them skills employers value','by shortening their studies','by replacing work experience completely']::text[],'B','''...help younger people gain skills and experience that employers value.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Volunteering is often presented as a selfless act, but research suggests it benefits volunteers too. Studies have linked regular volunteering with lower levels of stress and depression, especially among older people. Volunteering can also help younger people gain skills and experience that employers value. However, charities warn that volunteers need proper support and training; without it, they may feel undervalued and give up.',null,null,null,'practice'),
  ('ai:ai-batch-08:c0bf7ac86250','B2'::public.cefr_level,'reading','What do charities warn about?',array['Volunteers need support and training.','Volunteering is dangerous.','Volunteers should be paid.','There are too many volunteers.']::text[],'A','''...volunteers need proper support and training.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Volunteering is often presented as a selfless act, but research suggests it benefits volunteers too. Studies have linked regular volunteering with lower levels of stress and depression, especially among older people. Volunteering can also help younger people gain skills and experience that employers value. However, charities warn that volunteers need proper support and training; without it, they may feel undervalued and give up.',null,null,null,'practice'),
  ('ai:ai-batch-08:20176195e230','B2'::public.cefr_level,'reading','Which reason for pub closures is NOT given?',array['a ban on smoking','rising costs','changing drinking habits','cheaper supermarket alcohol']::text[],'A','The text lists rising costs, changing habits and cheaper supermarket alcohol.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The pub has been at the heart of British social life for centuries, but its future is uncertain. Thousands have closed over the past two decades, due to rising costs, changing drinking habits and cheaper alcohol in supermarkets. Some pubs have survived by diversifying: offering food, hosting quiz nights, or even housing a post office or shop. In several villages, residents have bought their local pub collectively to prevent it from closing.',null,null,null,'practice'),
  ('ai:ai-batch-08:3c7356f5bcc9','B2'::public.cefr_level,'reading','How have some pubs survived?',array['by banning food','by closing at weekends','by offering other services such as food or a shop','by raising prices']::text[],'C','''Some pubs have survived by diversifying.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The pub has been at the heart of British social life for centuries, but its future is uncertain. Thousands have closed over the past two decades, due to rising costs, changing drinking habits and cheaper alcohol in supermarkets. Some pubs have survived by diversifying: offering food, hosting quiz nights, or even housing a post office or shop. In several villages, residents have bought their local pub collectively to prevent it from closing.',null,null,null,'practice'),
  ('ai:ai-batch-08:2ef7676b65b9','B2'::public.cefr_level,'reading','What have residents done in several villages?',array['turned the pub into a house','bought their pub together','moved away','built a new pub']::text[],'B','''...residents have bought their local pub collectively.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The pub has been at the heart of British social life for centuries, but its future is uncertain. Thousands have closed over the past two decades, due to rising costs, changing drinking habits and cheaper alcohol in supermarkets. Some pubs have survived by diversifying: offering food, hosting quiz nights, or even housing a post office or shop. In several villages, residents have bought their local pub collectively to prevent it from closing.',null,null,null,'practice'),
  ('ai:ai-batch-08:18cdfb6be26e','B2'::public.cefr_level,'reading','What has reduced the cost of launching satellites?',array['government funding','smaller satellites only','reusable rockets','space stations']::text[],'C','''Reusable rockets have dramatically reduced the cost.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In recent years, private companies have become major players in space exploration, a field once dominated by governments. Reusable rockets have dramatically reduced the cost of launching satellites. Supporters say this competition will make space more accessible and drive innovation. Others worry about the growing amount of ''space junk'' — old satellites and debris orbiting the Earth — which could collide with working satellites.',null,null,null,'practice'),
  ('ai:ai-batch-08:ef7b400eda34','B2'::public.cefr_level,'reading','What is ''space junk''?',array['meteorites','rubbish thrown from rockets onto Earth','unused rocket designs','old satellites and debris orbiting the Earth']::text[],'D','''...old satellites and debris orbiting the Earth.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In recent years, private companies have become major players in space exploration, a field once dominated by governments. Reusable rockets have dramatically reduced the cost of launching satellites. Supporters say this competition will make space more accessible and drive innovation. Others worry about the growing amount of ''space junk'' — old satellites and debris orbiting the Earth — which could collide with working satellites.',null,null,null,'practice'),
  ('ai:ai-batch-08:3c9e7c8e9a17','B2'::public.cefr_level,'reading','Why is space junk a concern?',array['It could collide with working satellites.','It blocks sunlight.','It is too expensive to see.','It falls on cities every day.']::text[],'A','''...which could collide with working satellites.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','In recent years, private companies have become major players in space exploration, a field once dominated by governments. Reusable rockets have dramatically reduced the cost of launching satellites. Supporters say this competition will make space more accessible and drive innovation. Others worry about the growing amount of ''space junk'' — old satellites and debris orbiting the Earth — which could collide with working satellites.',null,null,null,'practice'),
  ('ai:ai-batch-08:8086c2f06f24','B2'::public.cefr_level,'reading','Why do peregrine falcons nest on tall buildings?',array['There are no predators anywhere else.','People feed them there.','They are warmer.','They resemble the cliffs they naturally use.']::text[],'D','''...tall buildings, which resemble the cliffs they naturally use.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Cities are often thought of as hostile to wildlife, yet some species thrive in urban environments. Foxes, for example, are common in many British cities, where they feed on food waste. Peregrine falcons nest on tall buildings, which resemble the cliffs they naturally use, and hunt pigeons. Urban planners are increasingly including green roofs, parks and wildlife corridors in new developments to support biodiversity.',null,null,null,'practice'),
  ('ai:ai-batch-08:28dfdc499b28','B2'::public.cefr_level,'reading','What do urban foxes feed on?',array['insects in parks only','food waste','plants','pigeons only']::text[],'B','''...where they feed on food waste.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Cities are often thought of as hostile to wildlife, yet some species thrive in urban environments. Foxes, for example, are common in many British cities, where they feed on food waste. Peregrine falcons nest on tall buildings, which resemble the cliffs they naturally use, and hunt pigeons. Urban planners are increasingly including green roofs, parks and wildlife corridors in new developments to support biodiversity.',null,null,null,'practice'),
  ('ai:ai-batch-08:d434293b9fee','B2'::public.cefr_level,'reading','How are planners supporting biodiversity?',array['with green roofs, parks and wildlife corridors','by removing trees','by banning foxes','by building taller towers']::text[],'A','''...including green roofs, parks and wildlife corridors.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Cities are often thought of as hostile to wildlife, yet some species thrive in urban environments. Foxes, for example, are common in many British cities, where they feed on food waste. Peregrine falcons nest on tall buildings, which resemble the cliffs they naturally use, and hunt pigeons. Urban planners are increasingly including green roofs, parks and wildlife corridors in new developments to support biodiversity.',null,null,null,'practice'),
  ('ai:ai-batch-08:040a9f7a39e3','B2'::public.cefr_level,'reading','What advantage do adult learners often have?',array['greater discipline and understanding','cheaper lessons','better hearing','more free time']::text[],'A','''...they often bring greater discipline and understanding.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Learning a musical instrument as an adult is entirely possible, despite the common belief that it must start in childhood. Adults may lack the time children have, but they often bring greater discipline and understanding. Teachers recommend short, regular practice sessions rather than occasional long ones, and setting realistic goals, such as learning a particular piece. Many adult learners say the greatest benefit is not perfection but the enjoyment and sense of achievement.',null,null,null,'practice'),
  ('ai:ai-batch-08:7b9189360984','B2'::public.cefr_level,'reading','What practice method do teachers recommend?',array['occasional long sessions','short, regular sessions','no practice at all','practising only before lessons']::text[],'B','''...short, regular practice sessions rather than occasional long ones.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Learning a musical instrument as an adult is entirely possible, despite the common belief that it must start in childhood. Adults may lack the time children have, but they often bring greater discipline and understanding. Teachers recommend short, regular practice sessions rather than occasional long ones, and setting realistic goals, such as learning a particular piece. Many adult learners say the greatest benefit is not perfection but the enjoyment and sense of achievement.',null,null,null,'practice'),
  ('ai:ai-batch-08:1c2b6864c126','B2'::public.cefr_level,'reading','What do adult learners value most?',array['enjoyment and a sense of achievement','perfect performance','passing exams','becoming professional']::text[],'A','''...the greatest benefit is not perfection but the enjoyment and sense of achievement.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Learning a musical instrument as an adult is entirely possible, despite the common belief that it must start in childhood. Adults may lack the time children have, but they often bring greater discipline and understanding. Teachers recommend short, regular practice sessions rather than occasional long ones, and setting realistic goals, such as learning a particular piece. Many adult learners say the greatest benefit is not perfection but the enjoyment and sense of achievement.',null,null,null,'practice'),
  ('ai:ai-batch-08:ad6405f8db92','B2'::public.cefr_level,'reading','What do residents of popular cities complain about?',array['poor public transport only','lack of hotels','too few tourists','rising rents and crowded streets']::text[],'D','''...rising rents, crowded streets and short-term holiday lets.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Some popular destinations are struggling with ''overtourism''. In cities like Venice and Barcelona, residents complain that rising rents, crowded streets and short-term holiday lets have changed their neighbourhoods. Authorities have responded with measures such as tourist taxes, limits on cruise ships and restrictions on new holiday rentals. Critics of these measures argue that tourism brings jobs and income, and that the solution is better management rather than discouraging visitors.',null,null,null,'practice'),
  ('ai:ai-batch-08:cd61557e581b','B2'::public.cefr_level,'reading','Which measure have authorities taken?',array['building more hotels','tourist taxes','banning all tourists','lowering rents']::text[],'B','''...tourist taxes, limits on cruise ships and restrictions on new holiday rentals.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Some popular destinations are struggling with ''overtourism''. In cities like Venice and Barcelona, residents complain that rising rents, crowded streets and short-term holiday lets have changed their neighbourhoods. Authorities have responded with measures such as tourist taxes, limits on cruise ships and restrictions on new holiday rentals. Critics of these measures argue that tourism brings jobs and income, and that the solution is better management rather than discouraging visitors.',null,null,null,'practice'),
  ('ai:ai-batch-08:25591f4f0246','B2'::public.cefr_level,'reading','What do critics of these measures argue?',array['Cruise ships should increase.','Tourists should be banned.','Taxes are too low.','Tourism brings jobs and needs better management.']::text[],'D','''...tourism brings jobs and income, and the solution is better management.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Some popular destinations are struggling with ''overtourism''. In cities like Venice and Barcelona, residents complain that rising rents, crowded streets and short-term holiday lets have changed their neighbourhoods. Authorities have responded with measures such as tourist taxes, limits on cruise ships and restrictions on new holiday rentals. Critics of these measures argue that tourism brings jobs and income, and that the solution is better management rather than discouraging visitors.',null,null,null,'practice'),
  ('ai:ai-batch-08:0df239251185','B2'::public.cefr_level,'reading','What have four-day week trials reported?',array['lower pay','more customer complaints','less stress and fewer sick days','longer working days']::text[],'C','''Trials have reported reduced stress and fewer sick days.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','An increasing number of companies are experimenting with a four-day working week without reducing pay. Supporters argue that staff are more focused and productive when they have more time to rest. Trials have reported reduced stress and fewer sick days. However, the model may be harder to apply in sectors such as healthcare or retail, where services must be provided every day, and some managers fear that customers will be inconvenienced.',null,null,null,'practice'),
  ('ai:ai-batch-08:2323bdc18353','B2'::public.cefr_level,'reading','In which sectors might the model be harder to apply?',array['banking','software and design','healthcare and retail','advertising']::text[],'C','''...harder to apply in sectors such as healthcare or retail.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','An increasing number of companies are experimenting with a four-day working week without reducing pay. Supporters argue that staff are more focused and productive when they have more time to rest. Trials have reported reduced stress and fewer sick days. However, the model may be harder to apply in sectors such as healthcare or retail, where services must be provided every day, and some managers fear that customers will be inconvenienced.',null,null,null,'practice'),
  ('ai:ai-batch-08:5c7622c974e5','B2'::public.cefr_level,'reading','What do supporters believe?',array['Rested staff are more productive.','Staff will work at weekends.','Customers prefer shorter weeks.','Companies will save money on salaries.']::text[],'A','''...staff are more focused and productive when they have more time to rest.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','An increasing number of companies are experimenting with a four-day working week without reducing pay. Supporters argue that staff are more focused and productive when they have more time to rest. Trials have reported reduced stress and fewer sick days. However, the model may be harder to apply in sectors such as healthcare or retail, where services must be provided every day, and some managers fear that customers will be inconvenienced.',null,null,null,'practice'),
  ('ai:ai-batch-08:4ea0be7c2071','B2'::public.cefr_level,'reading','How did ancient Central Americans consume cacao?',array['roasted like nuts','as sweet bars','as a bitter drink','as a medicine powder']::text[],'C','''...drank a bitter drink made from cacao beans.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Chocolate has a long history. The ancient peoples of Central America drank a bitter drink made from cacao beans, often flavoured with chilli. When the Spanish brought cacao to Europe in the 16th century, sugar was added and it became fashionable among the wealthy. Solid chocolate bars only appeared in the 19th century, when new machinery made it possible to process cacao on a large scale. Today, most cacao is grown in West Africa, where concerns remain about low incomes for farmers.',null,null,null,'practice'),
  ('ai:ai-batch-08:b03b2672e683','B2'::public.cefr_level,'reading','What changed when cacao reached Europe?',array['Bars were invented.','Chilli was added.','Sugar was added.','It became cheaper.']::text[],'C','''...sugar was added and it became fashionable among the wealthy.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Chocolate has a long history. The ancient peoples of Central America drank a bitter drink made from cacao beans, often flavoured with chilli. When the Spanish brought cacao to Europe in the 16th century, sugar was added and it became fashionable among the wealthy. Solid chocolate bars only appeared in the 19th century, when new machinery made it possible to process cacao on a large scale. Today, most cacao is grown in West Africa, where concerns remain about low incomes for farmers.',null,null,null,'practice'),
  ('ai:ai-batch-08:8245d47074be','B2'::public.cefr_level,'reading','Why did chocolate bars appear in the 19th century?',array['Spain introduced them.','Sugar became available.','Cacao began to grow in Europe.','New machinery allowed large-scale processing.']::text[],'D','''...new machinery made it possible to process cacao on a large scale.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Chocolate has a long history. The ancient peoples of Central America drank a bitter drink made from cacao beans, often flavoured with chilli. When the Spanish brought cacao to Europe in the 16th century, sugar was added and it became fashionable among the wealthy. Solid chocolate bars only appeared in the 19th century, when new machinery made it possible to process cacao on a large scale. Today, most cacao is grown in West Africa, where concerns remain about low incomes for farmers.',null,null,null,'practice'),
  ('ai:ai-batch-08:ae167b3f98a8','B2'::public.cefr_level,'reading','What concern is mentioned about cacao today?',array['low incomes for farmers','too little demand','high prices for chocolate','bad weather in Europe']::text[],'A','''...concerns remain about low incomes for farmers.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Chocolate has a long history. The ancient peoples of Central America drank a bitter drink made from cacao beans, often flavoured with chilli. When the Spanish brought cacao to Europe in the 16th century, sugar was added and it became fashionable among the wealthy. Solid chocolate bars only appeared in the 19th century, when new machinery made it possible to process cacao on a large scale. Today, most cacao is grown in West Africa, where concerns remain about low incomes for farmers.',null,null,null,'practice'),
  ('ai:ai-batch-08:a6fec3f99ca8','B2'::public.cefr_level,'reading','What do some studies say about homework at primary school?',array['It has no critics.','It strongly improves results.','It should be doubled.','There is little link with achievement.']::text[],'D','''...little link between homework and achievement at primary school.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The value of homework, particularly for younger children, is hotly debated. Some studies have found little link between homework and achievement at primary school, while at secondary level the benefits appear clearer. Critics argue that excessive homework causes stress and reduces time for play, sport and family life. Many schools now favour short, focused tasks, such as reading or practising times tables, rather than lengthy assignments.',null,null,null,'practice'),
  ('ai:ai-batch-08:44cfbcec9090','B2'::public.cefr_level,'reading','What do critics say excessive homework causes?',array['better behaviour','higher grades','stress and less time for other activities','more sleep']::text[],'C','''...causes stress and reduces time for play, sport and family life.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The value of homework, particularly for younger children, is hotly debated. Some studies have found little link between homework and achievement at primary school, while at secondary level the benefits appear clearer. Critics argue that excessive homework causes stress and reduces time for play, sport and family life. Many schools now favour short, focused tasks, such as reading or practising times tables, rather than lengthy assignments.',null,null,null,'practice'),
  ('ai:ai-batch-08:e5f3ddc4a3ce','B2'::public.cefr_level,'reading','What do many schools now prefer?',array['weekend tests','no homework at all','short, focused tasks','long research projects']::text[],'C','''...short, focused tasks... rather than lengthy assignments.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','The value of homework, particularly for younger children, is hotly debated. Some studies have found little link between homework and achievement at primary school, while at secondary level the benefits appear clearer. Critics argue that excessive homework causes stress and reduces time for play, sport and family life. Many schools now favour short, focused tasks, such as reading or practising times tables, rather than lengthy assignments.',null,null,null,'practice'),
  ('ai:ai-batch-08:c9fe0d910c50','B2'::public.cefr_level,'reading','What is ''range anxiety''?',array['worry about high prices','fear of car accidents','fear of running out of power before reaching a charger','fear of driving fast']::text[],'C','''...the fear of running out of power before reaching a charger.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Sales of electric cars have risen rapidly as prices fall and the number of charging points increases. Drivers praise the low running costs and quiet ride. However, many potential buyers remain hesitant, citing ''range anxiety'' — the fear of running out of power before reaching a charger — as well as the higher purchase price compared with petrol cars. Experts expect these concerns to fade as battery technology improves.',null,null,null,'practice'),
  ('ai:ai-batch-08:5e6b4b9aae03','B2'::public.cefr_level,'reading','What do electric car drivers praise?',array['long range','low running costs and a quiet ride','cheap purchase price','fast charging everywhere']::text[],'B','''Drivers praise the low running costs and quiet ride.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Sales of electric cars have risen rapidly as prices fall and the number of charging points increases. Drivers praise the low running costs and quiet ride. However, many potential buyers remain hesitant, citing ''range anxiety'' — the fear of running out of power before reaching a charger — as well as the higher purchase price compared with petrol cars. Experts expect these concerns to fade as battery technology improves.',null,null,null,'practice'),
  ('ai:ai-batch-08:ca91b864ae6d','B2'::public.cefr_level,'reading','What do experts expect to happen?',array['Charging points will close.','Petrol cars will become cheaper.','Sales will fall.','Buyers'' concerns will fade as batteries improve.']::text[],'D','''Experts expect these concerns to fade as battery technology improves.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Sales of electric cars have risen rapidly as prices fall and the number of charging points increases. Drivers praise the low running costs and quiet ride. However, many potential buyers remain hesitant, citing ''range anxiety'' — the fear of running out of power before reaching a charger — as well as the higher purchase price compared with petrol cars. Experts expect these concerns to fade as battery technology improves.',null,null,null,'practice'),
  ('ai:ai-batch-08:b94270cf89f4','B2'::public.cefr_level,'reading','Where is the novel set?',array['a city in Scotland','a fishing village in Cornwall','a London hospital','a ship at sea']::text[],'B','''...set in a fishing village on the Cornish coast.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','''The Silent Harbour'' is a gripping debut novel set in a fishing village on the Cornish coast. When a young woman disappears, the close-knit community is forced to confront long-buried secrets. The author creates a wonderfully atmospheric setting, and the main characters are convincingly drawn. If the ending feels slightly rushed, it is a minor flaw in an otherwise impressive book that will appeal to fans of literary crime fiction.',null,null,null,'practice'),
  ('ai:ai-batch-08:4a5f52f56054','B2'::public.cefr_level,'reading','What weakness does the reviewer mention?',array['The ending feels slightly rushed.','The characters are unconvincing.','The setting is dull.','It is too long.']::text[],'A','''If the ending feels slightly rushed, it is a minor flaw.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','''The Silent Harbour'' is a gripping debut novel set in a fishing village on the Cornish coast. When a young woman disappears, the close-knit community is forced to confront long-buried secrets. The author creates a wonderfully atmospheric setting, and the main characters are convincingly drawn. If the ending feels slightly rushed, it is a minor flaw in an otherwise impressive book that will appeal to fans of literary crime fiction.',null,null,null,'practice'),
  ('ai:ai-batch-08:bc8be57f5585','B2'::public.cefr_level,'reading','What is the reviewer''s overall opinion?',array['very positive','they did not finish it','negative','neutral']::text[],'A','''...an otherwise impressive book.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','''The Silent Harbour'' is a gripping debut novel set in a fishing village on the Cornish coast. When a young woman disappears, the close-knit community is forced to confront long-buried secrets. The author creates a wonderfully atmospheric setting, and the main characters are convincingly drawn. If the ending feels slightly rushed, it is a minor flaw in an otherwise impressive book that will appeal to fans of literary crime fiction.',null,null,null,'practice'),
  ('ai:ai-batch-08:405bff533303','B2'::public.cefr_level,'reading','For which texts is paper reading often better?',array['news headlines','short messages','longer and more complex texts','all texts equally']::text[],'C','''...for longer and more complex texts, readers often understand and remember more when reading on paper.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Researchers studying how people read on screens and on paper have found that, for longer and more complex texts, readers often understand and remember more when reading on paper. One explanation is that screens encourage skimming, as readers are used to scanning web pages quickly. However, the gap appears smaller among people who are trained to read carefully on screens, suggesting that habits matter as much as the medium itself.',null,null,null,'practice'),
  ('ai:ai-batch-08:2027fa053b37','B2'::public.cefr_level,'reading','What explanation is given?',array['Paper texts are shorter.','Screens damage eyes.','Screens encourage skimming.','Paper is easier to carry.']::text[],'C','''...screens encourage skimming.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Researchers studying how people read on screens and on paper have found that, for longer and more complex texts, readers often understand and remember more when reading on paper. One explanation is that screens encourage skimming, as readers are used to scanning web pages quickly. However, the gap appears smaller among people who are trained to read carefully on screens, suggesting that habits matter as much as the medium itself.',null,null,null,'practice'),
  ('ai:ai-batch-08:c03ef7c3f0d8','B2'::public.cefr_level,'reading','What does the research suggest at the end?',array['Screens should be banned.','Paper is always better.','Reading habits matter as much as the medium.','Training makes no difference.']::text[],'C','''...suggesting that habits matter as much as the medium itself.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Researchers studying how people read on screens and on paper have found that, for longer and more complex texts, readers often understand and remember more when reading on paper. One explanation is that screens encourage skimming, as readers are used to scanning web pages quickly. However, the gap appears smaller among people who are trained to read carefully on screens, suggesting that habits matter as much as the medium itself.',null,null,null,'practice'),
  ('ai:ai-batch-08:14bb92b2de32','B2'::public.cefr_level,'reading','What was the land like five years ago?',array['a farm','a school playground','full of rubbish','a car park']::text[],'C','''...an empty plot of land... was full of rubbish.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Five years ago, an empty plot of land in east Manchester was full of rubbish. Today it is a thriving community garden where local residents grow vegetables, keep bees and run cooking classes for children. The project was started by a group of neighbours who persuaded the council to lease them the land for a nominal fee. Organisers say the garden has brought together people of different ages and backgrounds who previously rarely spoke to each other.',null,null,null,'practice'),
  ('ai:ai-batch-08:c98fe6e888f9','B2'::public.cefr_level,'reading','How did the neighbours get the land?',array['A company donated it.','They took it without permission.','They bought it.','The council leased it to them for a small fee.']::text[],'D','''...persuaded the council to lease them the land for a nominal fee.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Five years ago, an empty plot of land in east Manchester was full of rubbish. Today it is a thriving community garden where local residents grow vegetables, keep bees and run cooking classes for children. The project was started by a group of neighbours who persuaded the council to lease them the land for a nominal fee. Organisers say the garden has brought together people of different ages and backgrounds who previously rarely spoke to each other.',null,null,null,'practice'),
  ('ai:ai-batch-08:e8858dd3cfe1','B2'::public.cefr_level,'reading','What social benefit do organisers mention?',array['It raised house prices.','It created jobs.','It reduced crime by half.','It brought together people who rarely spoke.']::text[],'D','''...brought together people of different ages and backgrounds who previously rarely spoke to each other.''',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Five years ago, an empty plot of land in east Manchester was full of rubbish. Today it is a thriving community garden where local residents grow vegetables, keep bees and run cooking classes for children. The project was started by a group of neighbours who persuaded the council to lease them the land for a nominal fee. Organisers say the garden has brought together people of different ages and backgrounds who previously rarely spoke to each other.',null,null,null,'practice'),
  ('ai:ai-batch-08:d9fa1edbd815','B2'::public.cefr_level,'reading','What does ''nominal'' fee mean here?',array['no fee at all','a very small, symbolic amount','a large fee','a monthly fee']::text[],'B','A nominal fee is a very small amount, not a real market price.',array['reading','story']::text[],'draft','unreviewed','ai-draft:ai-batch-08','Five years ago, an empty plot of land in east Manchester was full of rubbish. Today it is a thriving community garden where local residents grow vegetables, keep bees and run cooking classes for children. The project was started by a group of neighbours who persuaded the council to lease them the land for a nominal fee. Organisers say the garden has brought together people of different ages and backgrounds who previously rarely spoke to each other.',null,null,null,'practice'),
  ('ai:ai-batch-08:87ce8376959e','B2'::public.cefr_level,'grammar','It''s about time you ___ responsibility for your actions.',array['take','took','taking','will take']::text[],'B','''It''s about time + past simple''.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:c14b733c25c8','B2'::public.cefr_level,'grammar','The documents need ___ before Friday.',array['sign','to sign','signing','signed']::text[],'C','''Need + -ing'' with a passive meaning.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:606c565d221e','B2'::public.cefr_level,'grammar','He is likely ___ the award.',array['to win','won','win','winning']::text[],'A','''Be likely to'' + verb.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:59d47da24660','B2'::public.cefr_level,'grammar','They are bound ___ late — they always are.',array['to be','be','being','been']::text[],'A','''Be bound to'' = certainly will.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:84f4b4c2816e','B2'::public.cefr_level,'grammar','I''d have called you if I ___ your number.',array['would have','had','have had','had had']::text[],'D','Third conditional with ''have'' as main verb: had had.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:adadb19ff5e1','B2'::public.cefr_level,'grammar','Only when the results came out ___ how well she had done.',array['did she realise','she did realise','realised she','she realised']::text[],'A','''Only when...'' + inversion.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:328dfde935f9','B2'::public.cefr_level,'grammar','Under no circumstances ___ leave the building.',array['should you','you shouldn''t','you should','shouldn''t you']::text[],'A','''Under no circumstances'' + inversion; the negative is already in the phrase.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:5ca853391fa2','B2'::public.cefr_level,'grammar','The meeting, ___ was supposed to last an hour, went on all afternoon.',array['which','what','it','that']::text[],'A','Non-defining relative clause.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:08b1364ebad2','B2'::public.cefr_level,'grammar','He was made ___ his mistake publicly.',array['admitted','admitting','admit','to admit']::text[],'D','Passive ''make'': be made to do.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:512a1f1a18a0','B2'::public.cefr_level,'grammar','She is reported ___ two novels in prison.',array['writing','to write','to have written','that written']::text[],'C','Perfect infinitive for a completed past action.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:892137270b7c','B2'::public.cefr_level,'grammar','Rarely ___ such dedication in a young player.',array['you do see','see you','you see','do you see']::text[],'D','''Rarely'' + inversion.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:0475a22647bc','B2'::public.cefr_level,'grammar','I''m considering ___ abroad next year.',array['working','worked','to work','work']::text[],'A','''Consider'' + -ing.',array['grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:312e169467d9','B2'::public.cefr_level,'vocabulary','She managed to ___ the problem quickly.',array['reserve','revolve','resolve','revoke']::text[],'C','To resolve = solve.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:99f9268794f6','B2'::public.cefr_level,'vocabulary','The new evidence ___ doubt on his story.',array['throws up','casts','makes','puts']::text[],'B','''Cast doubt on'' = make it seem less likely.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:5fdee32de508','B2'::public.cefr_level,'vocabulary','We''re ___ out of time. Let''s finish quickly.',array['going','running','getting','coming']::text[],'B','''Run out of time''.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:da6cfaebefe3','B2'::public.cefr_level,'vocabulary','He gave a ___ performance as Hamlet.',array['memorised','memory','memorial','memorable']::text[],'D','Memorable = worth remembering.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:89c7590a1bd1','B2'::public.cefr_level,'vocabulary','There''s no ___ — we have to leave now.',array['alternative','alternate','altering','alteration']::text[],'A','An alternative = another option.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:fcf6ddb71900','B2'::public.cefr_level,'vocabulary','She''s very ___ — she can adapt to any situation.',array['versatile','vertical','volatile','verbal']::text[],'A','Versatile = able to do many things.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:273914bfdfc1','B2'::public.cefr_level,'vocabulary','The software is ___ with older computers.',array['competent','compatible','comparable','compulsory']::text[],'B','Compatible = able to work together.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:37e3acd2ddc6','B2'::public.cefr_level,'vocabulary','The tickets are ___ — you can''t get a refund.',array['unrefundable','refundless','non-refundable','not refund']::text[],'C','Non-refundable = money cannot be returned.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:48183f14b2fb','B2'::public.cefr_level,'vocabulary','The company was ___ by a larger competitor.',array['taken over','taken up','taken on','taken in']::text[],'A','''Take over'' = gain control of a company.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:6dd132c93625','B2'::public.cefr_level,'vocabulary','I''ll ___ the arrangements for the trip.',array['make','do','have','take']::text[],'A','''Make arrangements''.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:eb0bc096b3a6','B2'::public.cefr_level,'vocabulary','The two leaders ___ hands in front of the cameras.',array['gave','took','shaked','shook']::text[],'D','''Shake hands'' (past: shook).',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:2576bef7e03f','B2'::public.cefr_level,'vocabulary','The proposal ___ a lot of opposition.',array['met up','met on','meet with','met with']::text[],'D','''Meet with opposition'' = face it.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:0b97dc3abb5d','B2'::public.cefr_level,'vocabulary','Prices are expected to ___ off next year.',array['level','flat','equal','even up']::text[],'A','''Level off'' = stop rising or falling.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:7c78289da6ce','B2'::public.cefr_level,'vocabulary','She ___ her ambition of running a marathon.',array['relieved','archived','received','achieved']::text[],'D','To achieve an ambition = succeed in it.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:461a6383e628','B2'::public.cefr_level,'vocabulary','The ___ of the new policy will be felt for years.',array['consequently','consequent','consequences','sequences']::text[],'C','Consequences = results or effects.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:1909794d7a93','B2'::public.cefr_level,'vocabulary','He had a ___ escape when his car skidded off the road.',array['narrow','thin','close up','slim']::text[],'A','A narrow escape = only just avoiding danger.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:1e39cd358373','B2'::public.cefr_level,'vocabulary','There''s a ___ difference between the two words.',array['subtly','sublime','subtitle','subtle']::text[],'D','Subtle = small and not obvious.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:517d4702ff3c','B2'::public.cefr_level,'vocabulary','The conference ___ experts from around the world.',array['brought along to','brought in to','brought together','brought up']::text[],'C','''Bring together'' = gather.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:8ebdfb6e6d5e','B2'::public.cefr_level,'vocabulary','Her comments were taken out of ___.',array['context','content','contact','contest']::text[],'A','''Out of context'' = without the surrounding information.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:18764af81021','B2'::public.cefr_level,'vocabulary','It''s ___ that we leave before the storm arrives.',array['vitality','vitally','vital','vitamin']::text[],'C','Vital = extremely important.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice'),
  ('ai:ai-batch-08:a61a055dc846','B2'::public.cefr_level,'vocabulary','The village has a ___ community spirit.',array['powerful','heavy','strong','hard']::text[],'C','A strong community spirit.',array['vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-08',null,null,null,null,'practice')
on conflict (external_ref) do update set
  cefr_level = excluded.cefr_level, skill = excluded.skill, prompt = excluded.prompt,
  options = excluded.options, correct_option = excluded.correct_option,
  explanation = excluded.explanation, tags = excluded.tags, passage = excluded.passage,
  media_type = excluded.media_type, media_path = excluded.media_path, media_caption = excluded.media_caption,
  pool = excluded.pool
where public.assessment_questions.status = 'draft' and public.assessment_questions.review_status = 'unreviewed';
